import{_ as p,a0 as o,w as d,s as r,ao as l,I as a,x as n,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 上使用 NTP 保持精确的时间 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 NTP 保持精确的时间 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 NTP 保持精确的时间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 NTP 保持精确的时间 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180125 Keep Accurate Time on Linux with NTP","title":"在 Linux 上使用 NTP 保持精确的时间","tag":"201803","desc":""},"relativePath":"201803/20180125 Keep Accurate Time on Linux with NTP.md","filePath":"[post].md"}'),c={name:"201803/20180125 Keep Accurate Time on Linux with NTP.md"};function u(g,s,h,k,m,T){const e=o("Link");return d(),r("div",null,[s[30]||(s[30]=l(`<h1 id="在-linux-上使用-ntp-保持精确的时间" tabindex="-1">在 Linux 上使用 NTP 保持精确的时间 <a class="header-anchor" href="#在-linux-上使用-ntp-保持精确的时间" aria-label="Permalink to “在 Linux 上使用 NTP 保持精确的时间”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/usno-amc.jpg?itok=KA8HwI02" alt=""></p><p>如何保持正确的时间，如何使用 NTP 和 systemd 让你的计算机在不滥用时间服务器的前提下保持同步。</p><h3 id="它的时间是多少" tabindex="-1">它的时间是多少？ <a class="header-anchor" href="#它的时间是多少" aria-label="Permalink to “它的时间是多少？”">​</a></h3><p>让 Linux 来告诉你时间的时候，它是很奇怪的。你可能认为是使用 <code>time</code> 命令来告诉你时间，其实并不是，因为 <code>time</code> 只是一个测量一个进程运行了多少时间的计时器。为得到时间，你需要运行的是 <code>date</code> 命令，你想查看更多的日期，你可以运行 <code>cal</code> 命令。文件上的时间戳也是一个容易混淆的地方，因为根据你的发行版默认情况不同，它一般有两种不同的显示方法。下面是来自 Ubuntu 16.04 LTS 的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l</span></span>
<span class="line"><span>drwxrwxr-x 5 carla carla 4096 Mar 27 2017 stuff</span></span>
<span class="line"><span>drwxrwxr-x 2 carla carla 4096 Dec 8 11:32 things</span></span>
<span class="line"><span>-rw-rw-r-- 1 carla carla 626052 Nov 21 12:07 fatpdf.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 carla carla 2781 Apr 18 2017 oddlots.txt</span></span></code></pre></div>`,6)),a("p",null,[s[1]||(s[1]=n("有些显示年，有些显示时间，这样的方式让你的文件更混乱。GNU 默认的情况是，如果你的文件在六个月以内，则显示时间而不是年。我想这样做可能是有原因的。如果你的 Linux 是这样的，尝试用 ",-1)),s[2]||(s[2]=a("code",null,"ls -l --time-style=long-iso",-1)),s[3]||(s[3]=n(" 命令，让时间戳用同一种方式去显示，按字母顺序排序。请查阅 ",-1)),i(e,{href:"https://www.linux.com/learn/how-change-linux-date-and-time-simple-commands"},{default:t(()=>[...s[0]||(s[0]=[n("如何更改 Linux 的日期和时间：简单的命令",-1)])]),_:1}),s[4]||(s[4]=n(" 去学习 Linux 上管理时间的各种方法。",-1))]),s[31]||(s[31]=l(`<h3 id="检查当前设置" tabindex="-1">检查当前设置 <a class="header-anchor" href="#检查当前设置" aria-label="Permalink to “检查当前设置”">​</a></h3><p>NTP —— 网络时间协议，它是保持计算机正确时间的老式方法。<code>ntpd</code> 是 NTP 守护程序，它通过周期性地查询公共时间服务器来按需调整你的计算机时间。它是一个简单的、轻量级的协议，使用它的基本功能时设置非常容易。systemd 通过使用 <code>systemd-timesyncd.service</code> 已经越俎代庖地 “干了 NTP 的活”，它可以用作 <code>ntpd</code> 的客户端。</p><p>在我们开始与 NTP “打交道” 之前，先花一些时间来了检查一下当前的时间设置是否正确。</p><p>你的系统上（至少）有两个时钟：系统时间 —— 它由 Linux 内核管理，第二个是你的主板上的硬件时钟，它也称为实时时钟（RTC）。当你进入系统的 BIOS 时，你可以看到你的硬件时钟的时间，你也可以去改变它的设置。当你安装一个新的 Linux 时，在一些图形化的时间管理器中，你会被询问是否设置你的 RTC 为 UTC（<ruby>世界标准时间<rt>Coordinated Universal Time</rt></ruby>）时区，因为所有的时区和夏令时都是基于 UTC 的。你可以使用 <code>hwclock</code> 命令去检查：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo hwclock --debug</span></span>
<span class="line"><span>hwclock from util-linux 2.27.1</span></span>
<span class="line"><span>Using the /dev interface to the clock.</span></span>
<span class="line"><span>Hardware clock is on UTC time</span></span>
<span class="line"><span>Assuming hardware clock is kept in UTC time.</span></span>
<span class="line"><span>Waiting for clock tick...</span></span>
<span class="line"><span>...got clock tick</span></span>
<span class="line"><span>Time read from Hardware Clock: 2018/01/22 22:14:31</span></span>
<span class="line"><span>Hw clock time : 2018/01/22 22:14:31 = 1516659271 seconds since 1969</span></span>
<span class="line"><span>Time since last adjustment is 1516659271 seconds</span></span>
<span class="line"><span>Calculated Hardware Clock drift is 0.000000 seconds</span></span>
<span class="line"><span>Mon 22 Jan 2018 02:14:30 PM PST .202760 seconds</span></span></code></pre></div><p><code>Hardware clock is on UTC time</code> 表明了你的计算机的 RTC 是使用 UTC 时间的，虽然它把该时间转换为你的本地时间。如果它被设置为本地时间，它将显示 <code>Hardware clock is on local time</code>。</p><p>你应该有一个 <code>/etc/adjtime</code> 文件。如果没有的话，使用如下命令同步你的 RTC 为系统时间，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo hwclock -w</span></span></code></pre></div><p>这个命令将生成该文件，内容看起来类似如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/adjtime</span></span>
<span class="line"><span>0.000000 1516661953 0.000000</span></span>
<span class="line"><span>1516661953</span></span>
<span class="line"><span>UTC</span></span></code></pre></div><p>新发明的 systemd 方式是去运行 <code>timedatectl</code> 命令，运行它不需要 root 权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl</span></span>
<span class="line"><span> Local time: Mon 2018-01-22 14:17:51 PST</span></span>
<span class="line"><span> Universal time: Mon 2018-01-22 22:17:51 UTC</span></span>
<span class="line"><span> RTC time: Mon 2018-01-22 22:17:51</span></span>
<span class="line"><span> Time zone: America/Los_Angeles (PST, -0800)</span></span>
<span class="line"><span> Network time on: yes</span></span>
<span class="line"><span>NTP synchronized: yes</span></span>
<span class="line"><span> RTC in local TZ: no</span></span></code></pre></div><p><code>RTC in local TZ: no</code> 表明它使用 UTC 时间。那么怎么改成使用本地时间？这里有许多种方法可以做到。最简单的方法是使用一个图形配置工具，比如像 openSUSE 中的 YaST。你也可使用 <code>timedatectl</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl set-local-rtc 0</span></span></code></pre></div><p>或者编辑 <code>/etc/adjtime</code>，将 <code>UTC</code> 替换为 <code>LOCAL</code>。</p><h3 id="systemd-timesyncd-客户端" tabindex="-1">systemd-timesyncd 客户端 <a class="header-anchor" href="#systemd-timesyncd-客户端" aria-label="Permalink to “systemd-timesyncd 客户端”">​</a></h3><p>现在，我已经累了，但是我们刚到非常精彩的部分。谁能想到计时如此复杂？我们甚至还没有了解到它的皮毛；阅读 <code>man 8 hwclock</code> 去了解你的计算机如何保持时间的详细内容。</p><p>systemd 提供了 <code>systemd-timesyncd.service</code> 客户端，它可以查询远程时间服务器并调整你的本地系统时间。在 <code>/etc/systemd/timesyncd.conf</code> 中配置你的（时间）服务器。大多数 Linux 发行版都提供了一个默认配置，它指向他们维护的时间服务器上，比如，以下是 Fedora 的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Time]</span></span>
<span class="line"><span>#NTP=</span></span>
<span class="line"><span>#FallbackNTP=0.fedora.pool.ntp.org 1.fedora.pool.ntp.org</span></span></code></pre></div><p>你可以输入你希望使用的其它时间服务器，比如你自己的本地 NTP 服务器，在 <code>NTP=</code> 行上输入一个以空格分隔的服务器列表。（别忘了取消这一行的注释）<code>NTP=</code> 行上的任何内容都将覆盖掉 <code>FallbackNTP</code> 行上的配置项。</p><p>如果你不想使用 systemd 呢？那么，你将需要 NTP 就行。</p><h3 id="配置-ntp-服务器和客户端" tabindex="-1">配置 NTP 服务器和客户端 <a class="header-anchor" href="#配置-ntp-服务器和客户端" aria-label="Permalink to “配置 NTP 服务器和客户端”">​</a></h3>`,22)),a("p",null,[s[6]||(s[6]=n("配置你自己的局域网 NTP 服务器是一个非常好的实践，这样你的网内计算机就不需要不停查询公共 NTP 服务器。在大多数 Linux 上的 NTP 都来自 ",-1)),s[7]||(s[7]=a("code",null,"ntp",-1)),s[8]||(s[8]=n(" 包，它们大多都提供 ",-1)),s[9]||(s[9]=a("code",null,"/etc/ntp.conf",-1)),s[10]||(s[10]=n(" 文件去配置时间服务器。查阅 ",-1)),i(e,{href:"http://support.ntp.org/bin/view/Servers/NTPPoolServers"},{default:t(()=>[...s[5]||(s[5]=[n("NTP 时间服务器池",-1)])]),_:1}),s[11]||(s[11]=n(" 去找到你所在的区域的合适的 NTP 服务器池。然后在你的 ",-1)),s[12]||(s[12]=a("code",null,"/etc/ntp.conf",-1)),s[13]||(s[13]=n(" 中输入 4 - 5 个服务器，每个服务器用单独的一行：",-1))]),s[32]||(s[32]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>driftfile /var/ntp.drift</span></span>
<span class="line"><span>logfile /var/log/ntp.log</span></span>
<span class="line"><span>server 0.europe.pool.ntp.org</span></span>
<span class="line"><span>server 1.europe.pool.ntp.org</span></span>
<span class="line"><span>server 2.europe.pool.ntp.org</span></span>
<span class="line"><span>server 3.europe.pool.ntp.org</span></span></code></pre></div><p><code>driftfile</code> 告诉 <code>ntpd</code> 它需要保存用于启动时使用时间服务器快速同步你的系统时钟的信息。而日志也将保存在他们自己指定的目录中，而不是转储到 syslog 中。如果你的 Linux 发行版默认提供了这些文件，请使用它们。</p><p>现在去启动守护程序；在大多数主流的 Linux 中它的命令是 <code>sudo systemctl start ntpd</code>。让它运行几分钟之后，我们再次去检查它的状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ntpq -p</span></span>
<span class="line"><span> remote refid st t when poll reach delay offset jitter</span></span>
<span class="line"><span>==============================================================</span></span>
<span class="line"><span>+dev.smatwebdesi 192.168.194.89 3 u 25 64 37 92.456 -6.395 18.530</span></span>
<span class="line"><span>*chl.la 127.67.113.92 2 u 23 64 37 75.175 8.820 8.230</span></span>
<span class="line"><span>+four0.fairy.mat 35.73.197.144 2 u 22 64 37 116.272 -10.033 40.151</span></span>
<span class="line"><span>-195.21.152.161 195.66.241.2 2 u 27 64 37 107.559 1.822 27.346</span></span></code></pre></div><p>我不知道这些内容是什么意思，但重要的是，你的守护程序已经与时间服务器开始对话了，而这正是我们所需要的。你可以去运行 <code>sudo systemctl enable ntpd</code> 命令，永久启用它。如果你的 Linux 没有使用 systemd，那么，给你留下的家庭作业就是找出如何去运行 <code>ntpd</code>。</p><p>现在，你可以在你的局域网中的其它计算机上设置 <code>systemd-timesyncd</code>，这样它们就可以使用你的本地 NTP 服务器了，或者，在它们上面安装 NTP，然后在它们的 <code>/etc/ntp.conf</code> 上输入你的本地 NTP 服务器。</p><p>NTP 服务器会受到攻击，而且需求在不断增加。你可以通过运行你自己的公共 NTP 服务器来提供帮助。下周我们将学习如何运行你自己的公共服务器。</p>`,7)),a("p",null,[s[15]||(s[15]=n("通过来自 Linux 基金会和 edX 的免费课程 ",-1)),i(e,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:t(()=>[...s[14]||(s[14]=[n("“Linux 入门”",-1)])]),_:1}),s[16]||(s[16]=n(" 来学习更多 Linux 的知识。",-1))]),s[33]||(s[33]=a("hr",null,null,-1)),a("p",null,[s[18]||(s[18]=n("via: ",-1)),i(e,{href:"https://www.linux.com/learn/intro-to-linux/2018/1/keep-accurate-time-linux-ntp"},{default:t(()=>[...s[17]||(s[17]=[n("https://www.linux.com/learn/intro-to-linux/2018/1/keep-accurate-time-linux-ntp",-1)])]),_:1})]),a("p",null,[s[22]||(s[22]=n("作者：",-1)),i(e,{href:"https://www.linux.com/users/cschroder"},{default:t(()=>[...s[19]||(s[19]=[n("CARLA SCHRODER",-1)])]),_:1}),s[23]||(s[23]=n(" 译者：",-1)),i(e,{href:"https://github.com/qhwdw"},{default:t(()=>[...s[20]||(s[20]=[n("qhwdw",-1)])]),_:1}),s[24]||(s[24]=n(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[21]||(s[21]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[27]||(s[27]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[25]||(s[25]=[n("LCTT",-1)])]),_:1}),s[28]||(s[28]=n(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[26]||(s[26]=[n("Linux中国",-1)])]),_:1}),s[29]||(s[29]=n(" 荣誉推出",-1))])])}const y=p(c,[["render",u]]);export{x as __pageData,y as default};
